ROW.COLUMN:
-- kumarsu on 06/15/09 : changed the query as per PR39952, also replaced nvl with coalesce select g.extrl_ntity_seq_id , g.Effctv_Risk_Lvl , g.Actvty_Risk_Lvl , g.Tot_Trans_Amt , g.Tot_Trans_Ct from ( select t.extrl_ntity_seq_id , sum(t.Trxn_Base_Am) as Tot_Trans_Amt , count(1) as Tot_Trans_Ct --modified as per PR39952 , max(t.Efctv_Risk_Lvl) as Effctv_Risk_Lvl , max(t.Actvty_Risk_Lvl) as Actvty_Risk_Lvl from ( -- Wire trans - ORIG
select en.EXTRL_NTITY_SEQ_ID, en.EXTRL_NTITY_EFCTV_RISK_NB as Efctv_Risk_Lvl, w.ORIG_ACTVY_RISK_NB as Actvty_Risk_Lvl, w.DATA_DUMP_DT, w.TRXN_BASE_AM, case when en.EXTRL_NTITY_NM is not null then COALESCE(w.ORIG_EXTRL_NTITY_SEQ_ID, rownum) else null end as Other_Id, case when en.EXTRL_NTITY_NM is null then 1 else 0 end as Id_Driven, case when en.EXTRL_NTITY_NM is not null and w.ORIG_EXTRL_NTITY_SEQ_ID is null then 1 else 0 end as Nm_Driven -- The join condition was changed for improving the performance --BUG 19566952 - PERFORMANCE FIX from @MINER@.WIRE_TRXN w,@MINER@.EXTERNAL_ENTITY en where(w.ORIG_EXTRL_NTITY_SEQ_ID = en.EXTRL_NTITY_SEQ_ID or (w.ORIG_AUG_NM = en.EXTRL_NTITY_NM and w.ORIG_JRSDCN_CD = en.JRSDCN_CD))
and w.INTRL_ORIG_ACCT_FL <> 'Y' -- Include both Electronic Funds Transactions and Electronic Securities Transactions and w.MANTAS_TRXN_PRDCT_CD in (@Incl_Wire_Trxn_Prdct_Type_Lst) -- PR 32608 :Effective Risk Level of the Focal Entity Performing the Transactions >= Effctv Risk Lvl -- or Activity Risk Level of the Transactions performed by the Focal Entity >= Actvty Risk Lvl and (en.EXTRL_NTITY_EFCTV_RISK_NB >=@Effctv_Risk_Lvl or w.ORIG_ACTVY_RISK_NB >= @Actvty_Risk_Lvl) -- Exclude Distribution, Dividend, Fee, Interest, and Transfer-of-Account Transactions and w.MANTAS_TRXN_PURP_CD = 'GENERAL' -- Exclude Electronic Funds Transactions between Related Parties and (@Incl_Rltd_Parties ='Y' or COALESCE (w.UNRLTD_PARTY_FL,'Y') <>'N') -- Exclude Cancelled and Cancelling Electronic Funds Transactions and w.CXL_PAIR_TRXN_INTRL_ID is null --Included Transaction Source Codes or All Transaction Sources and (w.SRC_SYS_CD in (@Incl_Trans_Src_Lst) or @All_Trans_Src_Fl = 'Y') -- --------------------------------------------------------------------------------- -- Exclude Exempted EN and en.EXTRL_NTITY_EFCTV_RISK_NB <> -2 -- Getting data for look back period only and Utilize indexes --BUG 19566952 - PERFORMANCE FIX and w.TRXN_EXCTN_DT in (select cal.clndr_dt from @MANTAS@.KDD_cal cal where cal.CLNDR_NM = 'SYSCAL' and cal.CLNDR_DAY_AGE between 0 and @Look_Back_Period - 1) and w.DATA_DUMP_DT in (select cal.clndr_dt from @MANTAS@.KDD_cal cal where cal.CLNDR_NM = 'SYSCAL' and cal.CLNDR_DAY_AGE between 0 and @Look_Back_Period - 1) --OFSAABD-19350 --Included Jurisdiction Codes and (@All_Jurisdictions_Fl = 'Y' OR en.JRSDCN_CD IN (@Incl_Jurisdictions_Lst)) --********************************************************************************************* union all
-- Wire trans - SCND ORIG select en.EXTRL_NTITY_SEQ_ID, en.EXTRL_NTITY_EFCTV_RISK_NB as Efctv_Risk_Lvl, w.SCND_ORIG_ACTVY_RISK_NB as Actvty_Risk_Lvl, w.DATA_DUMP_DT, w.TRXN_BASE_AM, case when en.EXTRL_NTITY_NM is not null then COALESCE(w.SCND_ORIG_EXTRL_NTITY_SEQ_ID, rownum) else null end as Other_Id, case when en.EXTRL_NTITY_NM is null then 1 else 0 end as Id_Driven, case when en.EXTRL_NTITY_NM is not null and w.SCND_ORIG_EXTRL_NTITY_SEQ_ID is null then 1 else 0 end as Nm_Driven
from @MINER@.WIRE_TRXN w,@MINER@.EXTERNAL_ENTITY en where(w.SCND_ORIG_EXTRL_NTITY_SEQ_ID = en.EXTRL_NTITY_SEQ_ID or (w.SCND_ORIG_AUG_NM = en.EXTRL_NTITY_NM and w.SCND_ORIG_JRSDCN_CD = en.JRSDCN_CD))
and w.INTRL_SCND_ORIG_ACCT_FL <> 'Y' -- Exclude transaction where SCND_ORIG = ORIG and (w.INTRL_ORIG_ACCT_FL ='Y' or ( -- looking at second orig ID, make sure it's not same as orig ID (en.EXTRL_NTITY_NM is null and COALESCE(w.ORIG_EXTRL_NTITY_SEQ_ID, -1) <> w.SCND_ORIG_EXTRL_NTITY_SEQ_ID) or -- looking at second orig Name, make sure it's not same as orig name (en.EXTRL_NTITY_NM is not null and (COALESCE(w.ORIG_AUG_NM, '-') <> w.SCND_ORIG_AUG_NM or COALESCE(w.ORIG_JRSDCN_CD,'-') <> w.SCND_ORIG_JRSDCN_CD)))) -- Include both Electronic Funds Transactions and Electronic Securities Transactions and w.MANTAS_TRXN_PRDCT_CD in (@Incl_Wire_Trxn_Prdct_Type_Lst) -- PR 32608 :Effective Risk Level of the Focal Entity Performing the Transactions >= Effctv Risk Lvl -- or Activity Risk Level of the Transactions performed by the Focal Entity >= Actvty Risk Lvl and (en.EXTRL_NTITY_EFCTV_RISK_NB >=@Effctv_Risk_Lvl or w.SCND_ORIG_ACTVY_RISK_NB >= @Actvty_Risk_Lvl) -- Exclude Distribution, Dividend, Fee, Interest, and Transfer-of-Account Transactions and w.MANTAS_TRXN_PURP_CD = 'GENERAL' -- Exclude Electronic Funds Transactions between Related Parties and (@Incl_Rltd_Parties ='Y' or COALESCE (w.UNRLTD_PARTY_FL,'Y') <>'N') -- Exclude Cancelled and Canceling Electronic Funds Transactions and w.CXL_PAIR_TRXN_INTRL_ID is null --Included Transaction Source Codes or All Transaction Sources and (w.SRC_SYS_CD in (@Incl_Trans_Src_Lst) or @All_Trans_Src_Fl = 'Y') -- --------------------------------------------------------------------------------- -- Exclude Exempted EN and en.EXTRL_NTITY_EFCTV_RISK_NB <> -2 -- Getting data for look back period only and Utilize indexes and w.TRXN_EXCTN_DT in (select cal.clndr_dt from @MANTAS@.KDD_cal cal where cal.CLNDR_NM = 'SYSCAL' and cal.CLNDR_DAY_AGE between 0 and @Look_Back_Period - 1) and w.DATA_DUMP_DT in (select cal.clndr_dt from @MANTAS@.KDD_cal cal where cal.CLNDR_NM = 'SYSCAL' and cal.CLNDR_DAY_AGE between 0 and @Look_Back_Period - 1) --OFSAABD-19350 --Included Jurisdiction Codes and (@All_Jurisdictions_Fl = 'Y' OR en.JRSDCN_CD IN (@Incl_Jurisdictions_Lst)) --*********************************************************************************************** union all -- Wire trans - BENEF
select en.EXTRL_NTITY_SEQ_ID, en.extrl_ntity_efctv_risk_nb as Efctv_Risk_Lvl, w.BENEF_ACTVY_RISK_NB as Actvty_Risk_Lvl, w.DATA_DUMP_DT, w.TRXN_BASE_AM, case when en.EXTRL_NTITY_NM is not null then COALESCE(w.BENEF_EXTRL_NTITY_SEQ_ID, rownum) else null end as Other_Id, case when en.EXTRL_NTITY_NM is null then 1 else 0 end as Id_Driven, case when en.EXTRL_NTITY_NM is not null and w.BENEF_EXTRL_NTITY_SEQ_ID is null then 1 else 0 end as Nm_Driven
from @MINER@.WIRE_TRXN w,@MINER@.EXTERNAL_ENTITY en where (w.BENEF_EXTRL_NTITY_SEQ_ID = en.EXTRL_NTITY_SEQ_ID or (w.BENEF_AUG_NM = en.EXTRL_NTITY_NM and w.BENEF_JRSDCN_CD = en.JRSDCN_CD))
and w.INTRL_BENEF_ACCT_FL <> 'Y' -- Include both Electronic Funds Transactions and Electronic Securities Transactions and w.MANTAS_TRXN_PRDCT_CD in (@Incl_Wire_Trxn_Prdct_Type_Lst) -- PR 32608 :Effective Risk Level of the Focal Entity Performing the Transactions >= Effctv Risk Lvl -- or Activity Risk Level of the Transactions performed by the Focal Entity >= Actvty Risk Lvl and (en.EXTRL_NTITY_EFCTV_RISK_NB >=@Effctv_Risk_Lvl or w.BENEF_ACTVY_RISK_NB >= @Actvty_Risk_Lvl) -- Exclude Distribution, Dividend, Fee, Interest, and Transfer-of-Account Transactions and w.MANTAS_TRXN_PURP_CD = 'GENERAL' -- Exclude Electronic Funds Transactions between Related Parties and (@Incl_Rltd_Parties ='Y' or COALESCE (w.UNRLTD_PARTY_FL,'Y') <>'N') -- Exclude Cancelled and Canceling Electronic Funds Transactions and w.CXL_PAIR_TRXN_INTRL_ID is null --Included Transaction Source Codes or All Transaction Sources and (w.SRC_SYS_CD in (@Incl_Trans_Src_Lst) or @All_Trans_Src_Fl = 'Y') -- --------------------------------------------------------------------------------- -- Exclude Exempted EN and en.EXTRL_NTITY_EFCTV_RISK_NB <> -2 -- Getting data for look back period only and Utilize indexes and w.TRXN_EXCTN_DT in (select cal.clndr_dt from @MANTAS@.KDD_cal cal where cal.CLNDR_NM = 'SYSCAL' and cal.CLNDR_DAY_AGE between 0 and @Look_Back_Period - 1) and w.DATA_DUMP_DT in (select cal.clndr_dt from @MANTAS@.KDD_cal cal where cal.CLNDR_NM = 'SYSCAL' and cal.CLNDR_DAY_AGE between 0 and @Look_Back_Period - 1) --OFSAABD-19350 --Included Jurisdiction Codes and (@All_Jurisdictions_Fl = 'Y' OR en.JRSDCN_CD IN (@Incl_Jurisdictions_Lst)) --******************************************************************************************************* union all
-- Wire trans - SCND BENEF select en.EXTRL_NTITY_SEQ_ID, en.EXTRL_NTITY_EFCTV_RISK_NB as Efctv_Risk_Lvl, w.SCND_BENEF_ACTVY_RISK_NB as Actvty_Risk_Lvl, w.DATA_DUMP_DT, w.TRXN_BASE_AM, case when en.EXTRL_NTITY_NM is not null then COALESCE(w.SCND_BENEF_EXTRL_NTITY_SEQ_ID, rownum) else null end as Other_Id, case when en.EXTRL_NTITY_NM is null then 1 else 0 end as Id_Driven, case when en.EXTRL_NTITY_NM is not null and w.SCND_BENEF_EXTRL_NTITY_SEQ_ID is null then 1 else 0 end as Nm_Driven
from @MINER@.WIRE_TRXN w,@MINER@.EXTERNAL_ENTITY en where(w.SCND_BENEF_EXTRL_NTITY_SEQ_ID = en.EXTRL_NTITY_SEQ_ID or (w.SCND_BENEF_AUG_NM = en.EXTRL_NTITY_NM and w.SCND_BENEF_JRSDCN_CD = en.JRSDCN_CD))
and w.INTRL_SCND_BENEF_ACCT_FL <> 'Y' -- Exclude transaction where SCND_BENEF = BENEF and (w.INTRL_BENEF_ACCT_FL ='Y' or ( -- looking at second benef ID, make sure it's not same as benef ID (en.EXTRL_NTITY_NM is null and COALESCE(w.BENEF_EXTRL_NTITY_SEQ_ID, -1) <> w.SCND_BENEF_EXTRL_NTITY_SEQ_ID) or -- looking at second benef Name, make sure it's not same as benef name (en.EXTRL_NTITY_NM is not null and (COALESCE(w.BENEF_AUG_NM, '-') <> w.SCND_BENEF_AUG_NM or COALESCE(w.BENEF_JRSDCN_CD,'-') <> w.SCND_BENEF_JRSDCN_CD)))) -- Include both Electronic Funds Transactions and Electronic Securities Transactions and w.MANTAS_TRXN_PRDCT_CD in (@Incl_Wire_Trxn_Prdct_Type_Lst) -- PR 32608 :Effective Risk Level of the Focal Entity Performing the Transactions >= Effctv Risk Lvl -- or Activity Risk Level of the Transactions performed by the Focal Entity >= Actvty Risk Lvl and (en.EXTRL_NTITY_EFCTV_RISK_NB >=@Effctv_Risk_Lvl or w.SCND_BENEF_ACTVY_RISK_NB >= @Actvty_Risk_Lvl) -- Exclude Distribution, Dividend, Fee, Interest, and Transfer-of-Account Transactions and w.MANTAS_TRXN_PURP_CD = 'GENERAL' -- Exclude Electronic Funds Transactions between Related Parties and (@Incl_Rltd_Parties ='Y' or COALESCE (w.UNRLTD_PARTY_FL,'Y') <>'N') -- Exclude Cancelled and Canceling Electronic Funds Transactions and w.CXL_PAIR_TRXN_INTRL_ID is null --Included Transaction Source Codes or All Transaction Sources and (w.SRC_SYS_CD in (@Incl_Trans_Src_Lst) or @All_Trans_Src_Fl = 'Y') -- --------------------------------------------------------------------------------- -- Exclude Exempted EN and en.EXTRL_NTITY_EFCTV_RISK_NB <> -2 -- Getting data for look back period only and Utilize indexes and w.TRXN_EXCTN_DT in (select cal.clndr_dt from @MANTAS@.KDD_cal cal where cal.CLNDR_NM = 'SYSCAL' and cal.CLNDR_DAY_AGE between 0 and @Look_Back_Period - 1) and w.DATA_DUMP_DT in (select cal.clndr_dt from @MANTAS@.KDD_cal cal where cal.CLNDR_NM = 'SYSCAL' and cal.CLNDR_DAY_AGE between 0 and @Look_Back_Period - 1) --OFSAABD-19350 --Included Jurisdiction Codes and (@All_Jurisdictions_Fl = 'Y' OR en.JRSDCN_CD IN (@Incl_Jurisdictions_Lst)) ) t group by t.extrl_ntity_seq_id having -- added as per PR39952 (sum(t.Id_Driven) = count(1) or count(distinct t.Other_Id) > 1 or (sum(t.Nm_Driven) = 1 and count(1) = 1)) and -- Frequency_Period Period --BUG 19566952 - PERFORMANCE FIX max(t.DATA_DUMP_DT) in (select b.clndr_dt from @MANTAS@.KDD_cal b where b.CLNDR_NM = 'SYSCAL' and b.CLNDR_DAY_AGE between 0 and @Frequency_Period - 1)
) g WHERE (g.Tot_Trans_Amt >= @Min_Trans_Am or g.Tot_Trans_Ct >= @Min_Trans_Ct)
